package com.kareem.lifeos;

import android.app.Activity;
import android.content.Intent;
import android.os.Bundle;
import android.os.Handler;
import android.os.Looper;
import android.view.Gravity;
import android.view.View;
import android.widget.FrameLayout;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;
import androidx.swiperefreshlayout.widget.SwipeRefreshLayout;
import com.kareem.lifeos.actions.PersistentActionQueue;
import com.kareem.lifeos.actions.TeyaApprovalReceiver;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Date;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/** Now = focused command center. Everything visible here should answer “what matters now?” */
public final class FeedActivity extends Activity {
    private LifeDb db;private LinearLayout content;private SwipeRefreshLayout swipe;private TextView systemLine;private FrameLayout statusSpot;private final Handler ui=new Handler(Looper.getMainLooper());
    @Override public void onCreate(Bundle s){super.onCreate(s);db=new LifeDb(this);render();}
    @Override protected void onResume(){super.onResume();refresh();}
    @Override protected void onDestroy(){db.close();super.onDestroy();}

    private void render(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(LifeOsUi.BG);
        LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.setPadding(LifeOsUi.dp(this,16),LifeOsUi.dp(this,7),LifeOsUi.dp(this,12),LifeOsUi.dp(this,2));
        statusSpot=new FrameLayout(this);statusSpot.setClickable(true);statusSpot.setFocusable(true);statusSpot.setContentDescription("LifeOS intelligence status");statusSpot.setOnClickListener(v->startActivity(new Intent(this,MainActivity.class)));top.addView(statusSpot,new LinearLayout.LayoutParams(LifeOsUi.dp(this,24),LifeOsUi.dp(this,36)));
        TextView brand=LifeOsUi.text(this,"LifeOS",20.5f,LifeOsUi.TEXT);LifeOsUi.weight(brand,700);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(0,-2,1);bp.leftMargin=LifeOsUi.dp(this,8);top.addView(brand,bp);
        TextView avatar=LifeOsUi.avatar(this,"K");avatar.setContentDescription("Settings and diagnostics");avatar.setOnClickListener(v->startActivity(new Intent(this,MainActivity.class)));top.addView(avatar,new LinearLayout.LayoutParams(LifeOsUi.dp(this,36),LifeOsUi.dp(this,36)));root.addView(top);
        systemLine=LifeOsUi.text(this,"",9.8f,LifeOsUi.MUTED);LifeOsUi.weight(systemLine,500);systemLine.setPadding(LifeOsUi.dp(this,16),0,LifeOsUi.dp(this,16),LifeOsUi.dp(this,3));systemLine.setVisibility(View.GONE);root.addView(systemLine);
        ScrollView sc=new ScrollView(this);sc.setFillViewport(true);sc.setVerticalScrollBarEnabled(false);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(LifeOsUi.dp(this,16),LifeOsUi.dp(this,2),LifeOsUi.dp(this,16),LifeOsUi.dp(this,14));sc.addView(content);
        swipe=new SwipeRefreshLayout(this);swipe.setColorSchemeColors(LifeOsUi.BLUE);swipe.setProgressBackgroundColorSchemeColor(LifeOsUi.SURFACE);swipe.addView(sc);swipe.setOnRefreshListener(this::manualRefresh);root.addView(swipe,new LinearLayout.LayoutParams(-1,0,1));root.addView(LifeOsUi.bottomNav(this,FeedActivity.class));setContentView(root);
    }

    private void manualRefresh(){refresh();try{BackgroundBrain.poke(this);}catch(Throwable ignored){}if(!BackgroundModelManager.isReadyFast(this))NotificationBrain.analyzeForeground(this,r->{if(!isFinishing())refresh();});ui.postDelayed(()->{if(swipe!=null)swipe.setRefreshing(false);refresh();},1000);}

    private void refresh(){if(content==null)return;content.removeAllViews();IntelligenceStatus.Snapshot intelligence=IntelligenceStatus.snapshot(this);updateSystemStatus(intelligence);
        List<LifeDb.Loop> loops=db.openLoops(80);List<AttentionStore.Item> attention=AttentionStore.get(this).openItems(80);PersistentActionQueue queue=new PersistentActionQueue(this);List<PersistentActionQueue.Item> actions=queue.pending();List<SituationEngine.Situation> situations=SituationEngine.build(db,loops,actions,System.currentTimeMillis());
        int attentionCount=attentionCount(attention,loops),upcoming=countUpcoming(loops);
        TextView date=LifeOsUi.text(this,new SimpleDateFormat("EEE, d MMM yyyy",Locale.getDefault()).format(new Date()),10.8f,LifeOsUi.MUTED);LifeOsUi.weight(date,500);content.addView(date);
        TextView greet=LifeOsUi.text(this,greeting()+", Kareem.",21.5f,LifeOsUi.TEXT);LifeOsUi.weight(greet,700);greet.setPadding(0,LifeOsUi.dp(this,3),0,0);content.addView(greet);
        TextView sub=LifeOsUi.text(this,"Here's what matters right now.",11.7f,LifeOsUi.MUTED);LifeOsUi.weight(sub,500);sub.setPadding(0,LifeOsUi.dp(this,3),0,LifeOsUi.dp(this,10));content.addView(sub);
        stats(attentionCount,actions.size(),upcoming);

        sectionRow("Priority for today",attentionCount>0||!situations.isEmpty()?"See all":"",()->openSection("attention"));
        int shown=0;Set<Long> used=new HashSet<>();
        for(AttentionStore.Item x:attention){if(shown>=3)break;if(x.eventId<=0||!used.add(x.eventId))continue;attentionCard(x);shown++;}
        for(SituationEngine.Situation s:situations){if(shown>=3)break;if(s.latestEventId>0&&!used.add(s.latestEventId))continue;situationCard(s);shown++;}
        for(LifeDb.Loop l:loops){if(shown>=3)break;if(l.evidenceId<=0||!used.add(l.evidenceId))continue;loopCard(l);shown++;}
        if(shown==0)quiet("Nothing needs your attention right now.");

        if(!situations.isEmpty()){sectionRow("Active situations",situations.size()>3?"See all":"",()->openSection("situations"));for(int i=0;i<Math.min(3,situations.size());i++)situationCard(situations.get(i));}
        if(!actions.isEmpty()){sectionRow("Suggestions for you","See all",()->startActivity(new Intent(this,ActionCenterActivity.class)));for(int i=0;i<Math.min(2,actions.size());i++)approvalCard(queue,actions.get(i));}
    }

    private void updateSystemStatus(IntelligenceStatus.Snapshot s){statusSpot.removeAllViews();View ring=LifeOsUi.statusRing(this,s,20);statusSpot.addView(ring,new FrameLayout.LayoutParams(LifeOsUi.dp(this,20),LifeOsUi.dp(this,20),Gravity.CENTER));String line="";if("download_failed".equals(s.modelState)||"download_paused".equals(s.modelState)||"unavailable".equals(s.modelState))line="LifeOS needs attention · tap the ring for status";else if(s.pending>0||s.backgroundRunning||"downloading".equals(s.modelState)||"verifying".equals(s.modelState))line=s.pending>0?s.pending+" items analyzing in the background":"LifeOS is analyzing in the background";if(line.isEmpty())systemLine.setVisibility(View.GONE);else{systemLine.setText(line);systemLine.setTextColor("LifeOS needs attention · tap the ring for status".equals(line)?LifeOsUi.AMBER:LifeOsUi.MUTED);systemLine.setVisibility(View.VISIBLE);}}

    private void stats(int attention,int actions,int upcoming){LinearLayout row=new LinearLayout(this);stat(row,String.valueOf(attention),"Need attention",LifeOsIconView.ALERT,attention>0?LifeOsUi.RED:LifeOsUi.TERTIARY,()->openSection("attention"));stat(row,String.valueOf(actions),"Ready actions",LifeOsIconView.ACTION,LifeOsUi.BLUE,()->startActivity(new Intent(this,ActionCenterActivity.class)));stat(row,String.valueOf(upcoming),"Upcoming",LifeOsIconView.UPCOMING,LifeOsUi.TERTIARY,()->startActivity(new Intent(this,CapabilityActivity.class).putExtra("capability","events")));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=LifeOsUi.dp(this,2);content.addView(row,p);}
    private void stat(LinearLayout row,String value,String label,String iconName,int color,Runnable click){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(LifeOsUi.dp(this,8),LifeOsUi.dp(this,7),LifeOsUi.dp(this,6),LifeOsUi.dp(this,6));c.setBackground(LifeOsUi.round(this,LifeOsUi.SURFACE,LifeOsUi.BORDER,13));LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.addView(LifeOsUi.icon(this,iconName,color,12),new LinearLayout.LayoutParams(LifeOsUi.dp(this,12),LifeOsUi.dp(this,12)));TextView n=LifeOsUi.text(this,value,16.5f,color);LifeOsUi.weight(n,700);LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(-2,-2);np.leftMargin=LifeOsUi.dp(this,5);top.addView(n,np);c.addView(top);TextView l=LifeOsUi.text(this,label,9.1f,LifeOsUi.MUTED);LifeOsUi.weight(l,500);l.setPadding(0,LifeOsUi.dp(this,3),0,0);c.addView(l);c.setOnClickListener(v->click.run());c.setClickable(true);c.setFocusable(true);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,LifeOsUi.dp(this,56),1);p.setMargins(0,0,LifeOsUi.dp(this,6),0);row.addView(c,p);}
    private void sectionRow(String title,String action,Runnable click){LinearLayout r=new LinearLayout(this);r.setGravity(Gravity.CENTER_VERTICAL);r.setPadding(LifeOsUi.dp(this,1),LifeOsUi.dp(this,15),0,LifeOsUi.dp(this,7));TextView t=LifeOsUi.text(this,title,15.5f,LifeOsUi.TEXT);LifeOsUi.weight(t,700);r.addView(t,new LinearLayout.LayoutParams(0,-2,1));if(action!=null&&!action.isEmpty()){TextView a=LifeOsUi.text(this,action,10.5f,LifeOsUi.BLUE);LifeOsUi.weight(a,600);r.addView(a);r.setOnClickListener(v->click.run());}content.addView(r);}

    private void attentionCard(AttentionStore.Item x){LifeDb.Event e=db.eventById(x.eventId);LinearLayout c=LifeOsUi.card(this);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);View icon=e!=null&&PresentationSemantics.preferSemanticIcon(this,e)?LifeOsUi.iconTile(this,PresentationSemantics.iconName(this,e),PresentationSemantics.iconAccent(this,e),38):e==null?LifeOsUi.iconTile(this,LifeOsIconView.ALERT,LifeOsUi.RED,38):LifeOsUi.appIcon(this,e.app,38);row.addView(icon,new LinearLayout.LayoutParams(LifeOsUi.dp(this,38),LifeOsUi.dp(this,38)));LinearLayout txt=new LinearLayout(this);txt.setOrientation(LinearLayout.VERTICAL);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(0,-2,1);tp.setMargins(LifeOsUi.dp(this,10),0,LifeOsUi.dp(this,5),0);row.addView(txt,tp);final String title=e==null?UserFacingText.humanize(x.summary):PresentationSemantics.title(this,e);TextView t=LifeOsUi.text(this,title,12.8f,LifeOsUi.TEXT);LifeOsUi.weight(t,700);t.setMaxLines(1);txt.addView(t);String state=e==null?humanAction(x.action):PresentationSemantics.status(this,e);if(state.isEmpty())state=x.provisional?"Analyzing":"Waiting on you";TextView st=LifeOsUi.text(this,state,10.3f,x.provisional?LifeOsUi.AMBER:LifeOsUi.BLUE);LifeOsUi.weight(st,600);st.setPadding(0,LifeOsUi.dp(this,2),0,0);txt.addView(st);String initialSummary=e==null?UserFacingText.humanize(x.summary):PresentationSemantics.summary(this,e);final String summary=initialSummary.isEmpty()?UserFacingText.humanize(x.summary):initialSummary;TextView s=LifeOsUi.text(this,summary,10.5f,LifeOsUi.MUTED);LifeOsUi.weight(s,500);s.setPadding(0,LifeOsUi.dp(this,3),0,0);s.setMaxLines(2);txt.addView(s);row.addView(LifeOsUi.icon(this,LifeOsIconView.CHEVRON,LifeOsUi.TERTIARY,12),new LinearLayout.LayoutParams(LifeOsUi.dp(this,12),LifeOsUi.dp(this,18)));c.addView(row);c.setOnClickListener(v->startActivity(EntityDetailActivity.intent(this,"Attention",title,summary,x.eventId)));content.addView(c);}
    private void loopCard(LifeDb.Loop x){LifeDb.Event e=db.eventById(x.evidenceId);String title=e==null?UserFacingText.humanize(x.title):PresentationSemantics.title(this,e),summary=e==null?UserFacingText.humanize(x.title):PresentationSemantics.summary(this,e);LinearLayout c=LifeOsUi.card(this);LinearLayout r=new LinearLayout(this);r.setGravity(Gravity.CENTER_VERTICAL);r.addView(e==null?LifeOsUi.iconTile(this,LifeOsIconView.COMMITMENT,LifeOsUi.RED,38):LifeOsUi.appIcon(this,e.app,38),new LinearLayout.LayoutParams(LifeOsUi.dp(this,38),LifeOsUi.dp(this,38)));LinearLayout copy=new LinearLayout(this);copy.setOrientation(LinearLayout.VERTICAL);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(LifeOsUi.dp(this,10),0,LifeOsUi.dp(this,5),0);r.addView(copy,p);TextView t=LifeOsUi.text(this,title,12.8f,LifeOsUi.TEXT);LifeOsUi.weight(t,700);copy.addView(t);TextView st=LifeOsUi.text(this,x.dueAt>0?due(x.dueAt):humanKind(x.kind),10.3f,x.dueAt>0&&x.dueAt<System.currentTimeMillis()?LifeOsUi.RED:LifeOsUi.BLUE);LifeOsUi.weight(st,600);copy.addView(st);TextView b=LifeOsUi.text(this,summary,10.5f,LifeOsUi.MUTED);LifeOsUi.weight(b,500);b.setMaxLines(2);copy.addView(b);r.addView(LifeOsUi.icon(this,LifeOsIconView.CHEVRON,LifeOsUi.TERTIARY,12),new LinearLayout.LayoutParams(LifeOsUi.dp(this,12),LifeOsUi.dp(this,18)));c.addView(r);c.setOnClickListener(v->startActivity(EntityDetailActivity.intent(this,"Commitment",title,summary,x.evidenceId)));content.addView(c);}
    private void situationCard(SituationEngine.Situation s){LinearLayout c=LifeOsUi.card(this);LinearLayout r=new LinearLayout(this);r.setGravity(Gravity.CENTER_VERTICAL);r.addView(LifeOsUi.iconTile(this,LifeOsIconView.ACTIVITY,LifeOsUi.BLUE,38),new LinearLayout.LayoutParams(LifeOsUi.dp(this,38),LifeOsUi.dp(this,38)));LinearLayout copy=new LinearLayout(this);copy.setOrientation(LinearLayout.VERTICAL);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(LifeOsUi.dp(this,10),0,LifeOsUi.dp(this,5),0);r.addView(copy,p);TextView t=LifeOsUi.text(this,UserFacingText.humanize(s.title),12.8f,LifeOsUi.TEXT);LifeOsUi.weight(t,700);copy.addView(t);String state=s.actionCount>0&&s.attentionCount==0?"Action ready":"Needs attention";TextView st=LifeOsUi.text(this,state,10.3f,s.actionCount>0&&s.attentionCount==0?LifeOsUi.GREEN:LifeOsUi.BLUE);LifeOsUi.weight(st,600);copy.addView(st);TextView b=LifeOsUi.text(this,safeSituationSummary(s),10.5f,LifeOsUi.MUTED);LifeOsUi.weight(b,500);b.setPadding(0,LifeOsUi.dp(this,2),0,0);b.setMaxLines(2);copy.addView(b);r.addView(LifeOsUi.icon(this,LifeOsIconView.CHEVRON,LifeOsUi.TERTIARY,12),new LinearLayout.LayoutParams(LifeOsUi.dp(this,12),LifeOsUi.dp(this,18)));c.addView(r);c.setOnClickListener(v->startActivity(new Intent(this,SituationDetailActivity.class).putExtra("situation_id",s.id)));content.addView(c);}
    private void approvalCard(PersistentActionQueue queue,PersistentActionQueue.Item x){LinearLayout c=LifeOsUi.card(this);LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);head.addView(LifeOsUi.iconTile(this,LifeOsIconView.ACTION,LifeOsUi.GREEN,38),new LinearLayout.LayoutParams(LifeOsUi.dp(this,38),LifeOsUi.dp(this,38)));LinearLayout txt=new LinearLayout(this);txt.setOrientation(LinearLayout.VERTICAL);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(0,-2,1);tp.setMargins(LifeOsUi.dp(this,10),0,0,0);head.addView(txt,tp);String label=UserFacingText.humanize(x.proposal.payloadSummary.isEmpty()?x.proposal.actionType:x.proposal.payloadSummary);TextView t=LifeOsUi.text(this,label,12.7f,LifeOsUi.TEXT);LifeOsUi.weight(t,700);txt.addView(t);TextView meta=LifeOsUi.text(this,"Ready for your approval",10f,LifeOsUi.GREEN);LifeOsUi.weight(meta,600);meta.setPadding(0,LifeOsUi.dp(this,2),0,0);txt.addView(meta);if(!x.proposal.target.isEmpty()){TextView target=LifeOsUi.text(this,UserFacingText.humanize(x.proposal.target),10.5f,LifeOsUi.MUTED);LifeOsUi.weight(target,500);target.setPadding(0,LifeOsUi.dp(this,3),0,0);txt.addView(target);}c.addView(head);LinearLayout a=new LinearLayout(this);a.setPadding(0,LifeOsUi.dp(this,8),0,0);android.widget.Button details=LifeOsUi.button(this,"Review");details.setOnClickListener(v->startActivity(new Intent(this,SuggestedActionDetailActivity.class).putExtra("proposal_id",x.proposal.proposalId)));android.widget.Button approve=LifeOsUi.primary(this,"Approve");approve.setOnClickListener(v->{queue.decide(x.proposal.proposalId,true);TeyaApprovalReceiver.executeApproved(this,x);refresh();});a.addView(details,new LinearLayout.LayoutParams(0,LifeOsUi.dp(this,40),1));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,LifeOsUi.dp(this,40),1);p.setMargins(LifeOsUi.dp(this,7),0,0,0);a.addView(approve,p);c.addView(a);content.addView(c);}

    private int attentionCount(List<AttentionStore.Item> items,List<LifeDb.Loop> loops){Set<Long> ids=new HashSet<>();for(AttentionStore.Item i:items)if(i.eventId>0)ids.add(i.eventId);for(LifeDb.Loop l:loops)if(l.evidenceId>0)ids.add(l.evidenceId);return ids.size();}
    private int countUpcoming(List<LifeDb.Loop> loops){long now=System.currentTimeMillis();int n=0;for(LifeDb.Loop l:loops)if(l.dueAt>now)n++;return n;}
    private String safeSituationSummary(SituationEngine.Situation s){String raw=UserFacingText.humanize(s.summary);if(raw.matches(".*\\d{8,}.*")||raw.startsWith("Request ·")||raw.length()>170){String w=UserFacingText.humanize(s.why);String counts=(s.attentionCount>0?s.attentionCount+" open item"+(s.attentionCount==1?"":"s"):"")+(s.actionCount>0?(s.attentionCount>0?" · ":"")+s.actionCount+" action"+(s.actionCount==1?"":"s")+" ready":"");return (w+(counts.isEmpty()?"":" · "+counts)).trim();}return raw;}
    private void quiet(String text){TextView t=LifeOsUi.text(this,text,10.7f,LifeOsUi.MUTED);LifeOsUi.weight(t,500);t.setPadding(LifeOsUi.dp(this,2),LifeOsUi.dp(this,3),0,LifeOsUi.dp(this,5));content.addView(t);}
    private void openSection(String mode){startActivity(new Intent(this,FeedSectionActivity.class).putExtra("mode",mode));}
    private static String humanKind(String k){if(k==null||k.trim().isEmpty())return "Open item";String x=k.replace("brain_","").replace('_',' ').trim();return Character.toUpperCase(x.charAt(0))+x.substring(1);}
    private static String humanAction(String a){if(a==null||a.trim().isEmpty())return "";String x=a.replace('_',' ').trim();return Character.toUpperCase(x.charAt(0))+x.substring(1);}
    private static String due(long at){long d=at-System.currentTimeMillis(),day=86400000L;if(Math.abs(d)<day&&new SimpleDateFormat("yyyyMMdd",Locale.US).format(new Date(at)).equals(new SimpleDateFormat("yyyyMMdd",Locale.US).format(new Date())))return "Today";if(d<0)return "Overdue";if(d<2*day)return "Tomorrow";return new SimpleDateFormat("d MMM",Locale.getDefault()).format(new Date(at));}
    private static String greeting(){int h=Integer.parseInt(new SimpleDateFormat("H",Locale.US).format(new Date()));return h<12?"Good morning":h<18?"Good afternoon":"Good evening";}
}
